def nmse(a, b, dim=None, weights=None, skipna=False, keep_attrs=False, axis=None):
    \"\"\"Normalized Mean Squared Error.

    Parameters
    ----------
    a : :class:`xarray.DataArray`, :class:`xarray.Dataset`, ndarray
        Reference array (e.g. observations).
    b : :class:`xarray.DataArray`, :class:`xarray.Dataset`, ndarray
        Array to be evaluated (e.g. model).
    dim : str, :class:`list`, optional
        The dimension(s) to apply the function along. Note that this dimension will be reduced as a result. Defaults to ``None`` reducing all dimensions. Only used when ``a`` and ``b`` are of type ``xarray.DataArray`` or ``xarray.Dataset``.
    weights : :class:`xarray.DataArray`, ndarray, optional
        Weights matching dimensions of ``dim`` to apply during the function.
    skipna : bool, optional
        If True, skip NaNs when computing function.
    keep_attrs : bool, optional
        If True, the attributes (attrs) will be copied from the first input to the new one. If False (default), the new object will be returned without attributes. Only used when ``a`` and ``b`` are of types ``xarray.Dataset`` or ``xarray.DataArray``.
    axis : :class:`int`, optional
        The axis to apply the function along. Only used when ``a`` and ``b`` are of type ``np.ndarray`` or are array-like.

    Returns
    -------
    nmse : :class:`xarray.DataArray`, ndarray
        Normalized Mean Squared Error.
    \"\"\"
    if not isinstance(a, xr.DataArray) and not isinstance(b, xr.DataArray):
        if (dim is not None) and (axis is not None):
            warnings.warn(
                \"The `dim` keyword is unused with non xarray.DataArray inputs\"
            )
        if axis is None:
            axis = 0
            a = np.ravel(a)
            b = np.ravel(b)
            if weights is not None:
                weights = np.ravel(weights)

        mse = xs_internal._mse(a, b, axis=axis, weights=weights, skipna=skipna)

        if weights is None:
            var = np.nanvar(a, axis=axis) if skipna else np.var(a, axis=axis)
        else:
            if skipna:
                a_masked = np.ma.masked_invalid(a)
                b_masked = np.ma.masked_invalid(b)
                combined_mask = a_masked.mask | b_masked.mask
                a_final = np.ma.masked_array(a, mask=combined_mask)
                w_final = np.ma.masked_array(weights, mask=combined_mask)

                mean = np.ma.sum(w_final * a_final, axis=axis) / np.ma.sum(w_final, axis=axis)
                var = np.ma.sum(w_final * (a_final - mean)**2, axis=axis) / np.ma.sum(w_final, axis=axis)
                var = var.filled(np.nan)
            else:
                mean = np.sum(weights * a, axis=axis) / np.sum(weights, axis=axis)
                var = np.sum(weights * (a - mean)**2, axis=axis) / np.sum(weights, axis=axis)

        return mse / var
    else:
        if (dim is not None) and (axis is not None):
            warnings.warn(\"The `axis` keyword is unused with xarray.DataArray inputs\")

        mse = xs.mse(a, b, dim=dim, weights=weights, skipna=skipna, keep_attrs=keep_attrs)
        if weights is not None:
            var = a.weighted(weights).var(dim=dim, skipna=skipna)
        else:
            var = a.var(dim=dim, skipna=skipna)

        return mse / var

